  {"claim": "B plays online games that contain violence", "attribute": "specific gaming content", "mechanism": "negative tag question 'You won't... will you?' presupposes A has reason to suspect the positive is true", "evidence": [{"turn_id": 5, "quote": "You won't play online games full of violence , will you ?"}]}
